(() => {
const apiAvailable = window.location.protocol !== "file:";
const money = new Intl.NumberFormat("th-TH", { style: "currency", currency: "THB", maximumFractionDigits: 0 });
const cart = new Map();
let adminToken = localStorage.getItem("arotec_admin_token") || "";
let products = [];
const fallbackProducts = [
{ id: 1, sku: "NS-MIST-001", name: "Neuro-Scent Mist", subtitle: "สเปรย์กลิ่นบำบัด", category: "mist", product_type: "mist", price: 1290, stock_qty: 60, description: "A fine sensory mist designed for calm focus." },
{ id: 2, sku: "NR-SERUM-001", name: "Neural Recovery Body Serum", subtitle: "เซรั่มฟื้นฟูผิวกาย", category: "body-care", product_type: "pump", price: 1690, stock_qty: 42, description: "Body serum for post-stress skin comfort." },
{ id: 3, sku: "AH-BALM-001", name: "Adaptive Hand Balm", subtitle: "บาล์มบำรุงมือ", category: "skin-care", product_type: "tube", price: 890, stock_qty: 80, description: "Hand balm for barrier comfort and daily care." },
{ id: 4, sku: "SR-WASH-001", name: "Sensory Recover Wash", subtitle: "เจลอาบน้ำกลิ่นบำบัด", category: "wash", product_type: "pump", price: 990, stock_qty: 75, description: "A sensory wash for recovery rituals." },
{ id: 5, sku: "NS-CLEAN-001", name: "Neural Scalp Cleanser", subtitle: "แชมพูบำรุงหนังศีรษะ", category: "scalp-care", product_type: "dark-pump", price: 1290, stock_qty: 55, description: "Scalp cleanser for follicle care." }
];
const axis = [
{
key: "skin_state",
title: "Skin State (สภาพผิว)",
text: "สมดุลสภาพผิวปัจจุบันของคุณ",
value: 65,
color: "#b58a4a",
icon: '<svg viewBox="0 0 24 24"><circle cx="12" cy="8" r="4"></circle><path d="M5 21a7 7 0 0 1 14 0"></path><path d="M8 14c1.2.8 2.5 1.2 4 1.2s2.8-.4 4-1.2"></path></svg>'
},
{
key: "skin_axis",
title: "Skin Axis (แกนผิว)",
text: "สมดุลการทำงานและปฏิกิริยาของผิว",
value: 40,
color: "#769b66",
icon: '<svg viewBox="0 0 24 24"><path d="M12 3v18"></path><path d="M6 9h12"></path><path d="M7 19h10"></path><path d="M8 9l-3 6h6Z"></path><path d="M16 9l-3 6h6Z"></path></svg>'
},
{
key: "exposome",
title: "Environmental Exposome",
text: "สมดุลการรับมือกับปัจจัยสิ่งแวดล้อม",
value: 75,
color: "#80689d",
icon: '<svg viewBox="0 0 24 24"><path d="M4 20h16"></path><path d="M6 20V8l5-3v15"></path><path d="M13 20V6l5 3v11"></path><path d="M8 11h1"></path><path d="M8 15h1"></path><path d="M15 12h1"></path><path d="M15 16h1"></path></svg>'
}
];
const ingredients = [
{ title: "Stress Calm Complex", text: "ผ่อนคลายความเครียด", value: 20, color: "#d8b68a" },
{ title: "Barrier Support", text: "ฟื้นฟูเกราะป้องกันผิว", value: 25, color: "#e7c893" },
{ title: "Hydra Balance", text: "เพิ่มความชุ่มชื้น", value: 20, color: "#9ac9da" },
{ title: "Neuro-Aging Protect", text: "ชะลอวัยและปกป้องผิว", value: 15, color: "#dcc7a7" },
{ title: "Sensory Scent Blend", text: "กลิ่นบำบัดเฉพาะคุณ", value: 20, color: "#84a76d" }
];
const selectors = {
axisList: document.querySelector("[data-axis-list]"),
summaryAxis: document.querySelector("[data-summary-axis]"),
totalPercent: document.querySelector("[data-total-percent]"),
ingredientGrid: document.querySelector("[data-ingredient-grid]"),
mixBar: document.querySelector("[data-mix-bar]"),
mixTotal: document.querySelector("[data-mix-total]"),
productList: document.querySelector("[data-product-list]"),
formulaName: document.getElementById("formulaName"),
packageSize: document.getElementById("packageSize"),
formulaStatus: document.querySelector("[data-formula-status]"),
cartCount: document.querySelector("[data-cart-count]"),
cartDrawer: document.querySelector("[data-cart-drawer]"),
cartItems: document.querySelector("[data-cart-items]"),
cartTotal: document.querySelector("[data-cart-total]"),
checkoutModal: document.querySelector("[data-checkout-modal]"),
checkoutForm: document.querySelector("[data-checkout-form]"),
checkoutTotal: document.querySelector("[data-checkout-total]"),
checkoutStatus: document.querySelector("[data-checkout-status]"),
adminPanel: document.querySelector("[data-admin-panel]"),
adminLogin: document.querySelector("[data-admin-login]"),
adminWorkspace: document.querySelector("[data-admin-workspace]"),
adminStatus: document.querySelector("[data-admin-status]"),
adminPassword: document.getElementById("adminPassword"),
productForm: document.querySelector("[data-product-form]"),
adminProducts: document.querySelector("[data-admin-products]"),
adminOrders: document.querySelector("[data-admin-orders]"),
adminFormulas: document.querySelector("[data-admin-formulas]")
};
function escapeHtml(value) {
return String(value ?? "")
.replace(/&/g, "&amp;")
.replace(/</g, "&lt;")
.replace(/>/g, "&gt;")
.replace(/"/g, "&quot;")
.replace(/'/g, "&#039;");
}
async function api(path, options = {}) {
if (!apiAvailable) {
throw new Error("กรุณาเปิดเว็บผ่าน server.py เช่น http://127.0.0.1:8000/pages/customized.html");
}
const headers = { "Content-Type": "application/json", ...(options.headers || {}) };
const response = await fetch(path, { ...options, headers });
const data = await response.json().catch(() => ({}));
if (!response.ok || data.ok === false) {
throw new Error(data.error || `Request failed: ${response.status}`);
}
return data;
}
function baht(value) {
return money.format(Number(value || 0));
}
function currentFormula() {
const total = ingredients.reduce((sum, item) => sum + item.value, 0);
return {
formula_name: selectors.formulaName.value.trim() || "My Daily Neuro Balance",
package_size: selectors.packageSize.value,
skin_state: axis[0].value,
skin_axis: axis[1].value,
exposome: axis[2].value,
total_percent: total,
components: ingredients.map((item) => ({ title: item.title, percent: item.value }))
};
}
function renderAxis() {
selectors.axisList.innerHTML = axis.map((item, index) => `
<div class="axis-row">
<span class="axis-icon" aria-hidden="true">${item.icon}</span>
<div class="axis-copy">
<h3>${escapeHtml(item.title)}</h3>
<p>${escapeHtml(item.text)}</p>
<input class="shop-range" type="range" min="0" max="100" value="${item.value}" style="--range-color:${item.color};--value:${item.value}%" data-axis-index="${index}" aria-label="${escapeHtml(item.title)}">
<div class="range-scale"><span>0%</span><span>50%</span><span>100%</span></div>
</div>
<strong class="axis-value">${item.value}%</strong>
</div>
`).join("");
selectors.summaryAxis.innerHTML = axis.map((item) => `
<div class="summary-row" style="--row-color:${item.color};--row-value:${item.value}%">
<span><i></i>${escapeHtml(item.title.split(" (")[0])}</span>
<span></span>
<b>${item.value}%</b>
</div>
`).join("");
selectors.totalPercent.textContent = `${ingredients.reduce((sum, item) => sum + item.value, 0)}%`;
}
function renderIngredients() {
const total = ingredients.reduce((sum, item) => sum + item.value, 0);
selectors.ingredientGrid.innerHTML = ingredients.map((item, index) => `
<article class="ingredient-card" style="--ingredient-color:${item.color}">
<span class="ingredient-visual" aria-hidden="true"></span>
<h3>${escapeHtml(item.title)}</h3>
<p>${escapeHtml(item.text)}</p>
<input class="shop-range" type="range" min="0" max="100" value="${item.value}" style="--range-color:${item.color};--value:${item.value}%" data-ingredient-index="${index}" aria-label="${escapeHtml(item.title)}">
<div class="ingredient-controls">
<button type="button" data-ingredient-minus="${index}" aria-label="Decrease">−</button>
<strong>${item.value}%</strong>
<button type="button" data-ingredient-plus="${index}" aria-label="Increase">+</button>
</div>
</article>
`).join("");
selectors.mixBar.style.setProperty("--mix-width", `${Math.min(total, 100)}%`);
selectors.mixTotal.textContent = `${total}%`;
selectors.totalPercent.textContent = `${total}%`;
}
function balanceIngredients(changedIndex, nextValue) {
const oldValue = ingredients[changedIndex].value;
let delta = Math.max(0, Math.min(100, nextValue)) - oldValue;
if (!delta) return;
ingredients[changedIndex].value += delta;
const direction = delta > 0 ? -1 : 1;
let remaining = Math.abs(delta);
for (let offset = 1; offset < ingredients.length && remaining > 0; offset += 1) {
const index = (changedIndex + offset) % ingredients.length;
const available = direction < 0 ? ingredients[index].value : 100 - ingredients[index].value;
const amount = Math.min(available, remaining);
ingredients[index].value += amount * direction;
remaining -= amount;
}
if (remaining > 0) {
ingredients[changedIndex].value -= remaining * Math.sign(delta);
}
ingredients.forEach((item) => {
item.value = Math.max(0, Math.min(100, Math.round(item.value)));
});
const total = ingredients.reduce((sum, item) => sum + item.value, 0);
if (total !== 100) {
ingredients[ingredients.length - 1].value += 100 - total;
}
}
function productObjectType(product) {
return ["mist", "pump", "tube", "dark-pump", "jar"].includes(product.product_type)
? product.product_type
: "mist";
}
function renderProducts() {
selectors.productList.innerHTML = products.map((product) => `
<article class="shop-product-card">
<div class="product-mockup">
<span class="product-object ${productObjectType(product)}" data-label="A&S"></span>
</div>
<div class="shop-product-body">
<h3>${escapeHtml(product.name)}</h3>
<p>${escapeHtml(product.subtitle || product.description || product.category)}</p>
<div class="product-price-row">
<strong>${baht(product.price)}</strong>
<button type="button" data-add-cart="${product.id}" aria-label="Add ${escapeHtml(product.name)} to cart">
<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6h15l-2 8H8L6 3H3"></path><circle cx="9" cy="20" r="1.5"></circle><circle cx="18" cy="20" r="1.5"></circle><path d="M12 9v4"></path><path d="M10 11h4"></path></svg>
</button>
</div>
</div>
</article>
`).join("");
}
async function loadProducts() {
try {
const data = await api("/api/catalog/products");
products = data.products || [];
} catch (error) {
products = fallbackProducts;
selectors.formulaStatus.textContent = error.message;
}
renderProducts();
}
function addToCart(productId, quantity = 1) {
const product = products.find((item) => Number(item.id) === Number(productId));
if (!product) return;
const existing = cart.get(Number(product.id)) || { product, quantity: 0 };
existing.quantity = Math.min(existing.quantity + quantity, Math.max(1, Number(product.stock_qty || 99)));
cart.set(Number(product.id), existing);
renderCart();
}
function cartTotals() {
let count = 0;
let total = 0;
for (const item of cart.values()) {
count += item.quantity;
total += Number(item.product.price || 0) * item.quantity;
}
return { count, total };
}
function renderCart() {
const totals = cartTotals();
selectors.cartCount.textContent = totals.count;
selectors.cartTotal.textContent = baht(totals.total);
selectors.checkoutTotal.textContent = baht(totals.total);
if (!cart.size) {
selectors.cartItems.innerHTML = `<p>ยังไม่มีสินค้าในตะกร้า</p>`;
return;
}
selectors.cartItems.innerHTML = [...cart.values()].map((item) => `
<article class="cart-item">
<div>
<h3>${escapeHtml(item.product.name)}</h3>
<p>${baht(item.product.price)} × ${item.quantity}</p>
</div>
<div class="cart-qty">
<button type="button" data-cart-dec="${item.product.id}">−</button>
<span>${item.quantity}</span>
<button type="button" data-cart-inc="${item.product.id}">+</button>
</div>
</article>
`).join("");
}
function openCart() {
selectors.cartDrawer.classList.add("open");
selectors.cartDrawer.setAttribute("aria-hidden", "false");
}
function closeCart() {
selectors.cartDrawer.classList.remove("open");
selectors.cartDrawer.setAttribute("aria-hidden", "true");
}
async function saveFormula() {
selectors.formulaStatus.textContent = "กำลังบันทึกสูตร...";
try {
const data = await api("/api/formulas", {
method: "POST",
body: JSON.stringify(currentFormula())
});
selectors.formulaStatus.textContent = `บันทึกสูตรแล้ว: ${data.formula.formula_code}`;
} catch (error) {
selectors.formulaStatus.textContent = error.message;
}
}
function addRecommendations() {
products.slice(0, 3).forEach((product) => addToCart(product.id, 1));
openCart();
}
async function checkout(event) {
event.preventDefault();
selectors.checkoutStatus.textContent = "กำลังสร้างคำสั่งซื้อ...";
const formData = new FormData(selectors.checkoutForm);
const items = [...cart.values()].map((item) => ({
product_id: item.product.id,
quantity: item.quantity
}));
try {
const data = await api("/api/orders", {
method: "POST",
body: JSON.stringify({
customer: {
name: formData.get("name"),
email: formData.get("email"),
phone: formData.get("phone"),
address: formData.get("address")
},
note: formData.get("note"),
formula: currentFormula(),
items
})
});
selectors.checkoutStatus.textContent = `สั่งซื้อสำเร็จ หมายเลข ${data.order.order_code}`;
cart.clear();
renderCart();
await loadProducts();
} catch (error) {
selectors.checkoutStatus.textContent = error.message;
}
}
function showAdminPanel() {
selectors.adminPanel.hidden = false;
selectors.adminPanel.scrollIntoView({ behavior: "smooth", block: "start" });
if (adminToken) {
selectors.adminPassword.value = adminToken;
}
}
async function adminFetch(path, options = {}) {
return api(path, {
...options,
headers: {
Authorization: `Bearer ${adminToken}`,
...(options.headers || {})
}
});
}
function table(headers, rows) {
if (!rows.length) return "<p>ยังไม่มีข้อมูล</p>";
return `
<table>
<thead><tr>${headers.map((head) => `<th>${escapeHtml(head.label)}</th>`).join("")}</tr></thead>
<tbody>
${rows.map((row) => `
<tr>${headers.map((head) => `<td>${head.render ? head.render(row) : escapeHtml(row[head.key])}</td>`).join("")}</tr>
`).join("")}
</tbody>
</table>
`;
}
async function loadAdminData() {
selectors.adminStatus.textContent = "กำลังโหลดข้อมูลหลังบ้าน...";
try {
const [productData, orderData, formulaData] = await Promise.all([
adminFetch("/api/admin/products"),
adminFetch("/api/admin/orders"),
adminFetch("/api/admin/formulas")
]);
renderAdminProducts(productData.products || []);
renderAdminOrders(orderData.orders || []);
renderAdminFormulas(formulaData.formulas || []);
selectors.adminLogin.hidden = true;
selectors.adminWorkspace.hidden = false;
selectors.adminStatus.textContent = "";
} catch (error) {
selectors.adminStatus.textContent = error.message;
}
}
function renderAdminProducts(rows) {
selectors.adminProducts.innerHTML = table(
[
{ label: "SKU", key: "sku" },
{ label: "Name", key: "name" },
{ label: "Price", render: (row) => baht(row.price) },
{ label: "Stock", key: "stock_qty" },
{ label: "Status", render: (row) => Number(row.active) === 0 || row.active === false ? "Inactive" : "Active" },
{
label: "Action",
render: (row) => `<button type="button" data-edit-product="${row.id}">Edit</button> <button type="button" data-delete-product="${row.id}">Close</button>`
}
],
rows
);
}
function renderAdminOrders(rows) {
selectors.adminOrders.innerHTML = table(
[
{ label: "Order", key: "order_code" },
{ label: "Customer", render: (row) => `${escapeHtml(row.customer_name)}<br>${escapeHtml(row.customer_email)}` },
{ label: "Total", render: (row) => baht(row.total) },
{ label: "Status", key: "status" },
{ label: "Items", render: (row) => (row.items || []).map((item) => `${escapeHtml(item.name)} × ${item.quantity}`).join("<br>") },
{ label: "Date", key: "created_at" }
],
rows
);
}
function renderAdminFormulas(rows) {
selectors.adminFormulas.innerHTML = table(
[
{ label: "Formula", key: "formula_code" },
{ label: "Name", key: "formula_name" },
{ label: "Axis", render: (row) => `Skin ${row.skin_state}%<br>Axis ${row.skin_axis}%<br>Exposome ${row.exposome}%` },
{ label: "Package", key: "package_size" },
{ label: "Customer", render: (row) => `${escapeHtml(row.customer_name || "-")}<br>${escapeHtml(row.customer_email || "")}` },
{ label: "Date", key: "created_at" }
],
rows
);
}
function fillProductForm(product) {
const form = selectors.productForm;
form.elements.id.value = product.id || "";
form.elements.sku.value = product.sku || "";
form.elements.name.value = product.name || "";
form.elements.subtitle.value = product.subtitle || "";
form.elements.category.value = product.category || "";
form.elements.product_type.value = product.product_type || "mist";
form.elements.price.value = product.price || 0;
form.elements.stock_qty.value = product.stock_qty || 0;
form.elements.description.value = product.description || "";
form.elements.active.value = Number(product.active) === 0 || product.active === false ? "false" : "true";
}
function productFromForm() {
const form = selectors.productForm;
return {
sku: form.elements.sku.value,
name: form.elements.name.value,
subtitle: form.elements.subtitle.value,
category: form.elements.category.value,
product_type: form.elements.product_type.value,
price: Number(form.elements.price.value || 0),
stock_qty: Number(form.elements.stock_qty.value || 0),
description: form.elements.description.value,
active: form.elements.active.value === "true",
image_url: ""
};
}
async function saveAdminProduct(event) {
event.preventDefault();
const id = selectors.productForm.elements.id.value;
try {
await adminFetch(id ? `/api/admin/products/${id}` : "/api/admin/products", {
method: id ? "PUT" : "POST",
body: JSON.stringify(productFromForm())
});
selectors.productForm.reset();
selectors.productForm.elements.id.value = "";
await loadAdminData();
await loadProducts();
} catch (error) {
selectors.adminStatus.textContent = error.message;
}
}
function bindEvents() {
document.addEventListener("input", (event) => {
const axisIndex = event.target.dataset.axisIndex;
const ingredientIndex = event.target.dataset.ingredientIndex;
if (axisIndex !== undefined) {
axis[Number(axisIndex)].value = Number(event.target.value);
renderAxis();
}
if (ingredientIndex !== undefined) {
balanceIngredients(Number(ingredientIndex), Number(event.target.value));
renderIngredients();
renderAxis();
}
});
document.addEventListener("click", async (event) => {
const addId = event.target.closest("[data-add-cart]")?.dataset.addCart;
const incId = event.target.closest("[data-cart-inc]")?.dataset.cartInc;
const decId = event.target.closest("[data-cart-dec]")?.dataset.cartDec;
const minus = event.target.closest("[data-ingredient-minus]")?.dataset.ingredientMinus;
const plus = event.target.closest("[data-ingredient-plus]")?.dataset.ingredientPlus;
const editId = event.target.closest("[data-edit-product]")?.dataset.editProduct;
const deleteId = event.target.closest("[data-delete-product]")?.dataset.deleteProduct;
if (addId) addToCart(addId);
if (incId) addToCart(incId);
if (decId) {
const item = cart.get(Number(decId));
if (item) {
item.quantity -= 1;
if (item.quantity <= 0) cart.delete(Number(decId));
renderCart();
}
}
if (minus !== undefined) {
balanceIngredients(Number(minus), ingredients[Number(minus)].value - 5);
renderIngredients();
renderAxis();
}
if (plus !== undefined) {
balanceIngredients(Number(plus), ingredients[Number(plus)].value + 5);
renderIngredients();
renderAxis();
}
if (editId) {
const data = await adminFetch("/api/admin/products");
const product = (data.products || []).find((item) => Number(item.id) === Number(editId));
if (product) fillProductForm(product);
}
if (deleteId && window.confirm("ปิดการขายสินค้านี้?")) {
await adminFetch(`/api/admin/products/${deleteId}`, { method: "DELETE" });
await loadAdminData();
await loadProducts();
}
});
document.querySelector("[data-open-cart]").addEventListener("click", openCart);
document.querySelector("[data-close-cart]").addEventListener("click", closeCart);
selectors.cartDrawer.addEventListener("click", (event) => {
if (event.target === selectors.cartDrawer) closeCart();
});
document.querySelector("[data-open-checkout]").addEventListener("click", () => {
if (!cart.size) return;
selectors.checkoutModal.hidden = false;
closeCart();
});
document.querySelector("[data-close-checkout]").addEventListener("click", () => {
selectors.checkoutModal.hidden = true;
});
selectors.checkoutForm.addEventListener("submit", checkout);
document.querySelector("[data-save-formula]").addEventListener("click", saveFormula);
document.querySelector("[data-add-recommendations]").addEventListener("click", addRecommendations);
document.querySelector("[data-refresh-products]").addEventListener("click", loadProducts);
document.querySelector("[data-open-admin]").addEventListener("click", showAdminPanel);
document.querySelector("[data-close-admin]").addEventListener("click", () => {
selectors.adminPanel.hidden = true;
});
document.querySelector("[data-admin-login-button]").addEventListener("click", async () => {
adminToken = selectors.adminPassword.value.trim();
localStorage.setItem("arotec_admin_token", adminToken);
await loadAdminData();
});
selectors.productForm.addEventListener("submit", saveAdminProduct);
document.querySelector("[data-reset-product-form]").addEventListener("click", () => {
selectors.productForm.reset();
selectors.productForm.elements.id.value = "";
});
}
renderAxis();
renderIngredients();
renderCart();
bindEvents();
loadProducts();
})();